def announce(func):
    def wrapper(*args, **kwargs):
        print(f"{func.__name__} 호출")
        result = func(*args, **kwargs)
        print(f"결과: {result}")
        return result
    return wrapper

@announce
def add(a, b):
    return a + b

add(2, 3)

from functools import wraps

def count_calls(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        wrapper.calls += 1
        return func(*args, **kwargs)
    wrapper.calls = 0
    return wrapper

@count_calls
def hello():
    return "hi"

hello()
hello()
print(hello.calls, hello.__name__)

