exercises.solution:
def positive_only(func):
    def wrapper(*args, **kwargs):
        for a in args:
            if a < 0:
                raise ValueError("음수는 허용되지 않습니다")
        return func(*args, **kwargs)
    return wrapper


@positive_only
def total(*numbers):
    return sum(numbers)


def check(values):
    return total(*values)
